-- Series 89C-10/20/30/60 (3-piece cryogenic, quote-only Price NULL). Run from file (SSMS). Self-cleaning on re-run.
IF NOT EXISTS (SELECT 1 FROM Categories WHERE Name = N'Series 89C-10/20/30/60')
    INSERT INTO Categories (Name, Description, BodyMaterial, SeatMaterial, Design, TemperatureRange, KeyFeatures)
    VALUES (N'Series 89C-10/20/30/60',
        N'The Mars Series 89C-10/20/30/60 is a 3-piece, full-port cryogenic ball valve with an ISO 5211 mounting pad, blow-out-proof stem and a 17-4PH stem, designed for liquid nitrogen, helium, CO2 and other liquefied gases. Rated -196 to +120 degree C; 2250 PSI on threaded/weld ends and ANSI #150/300/600 on flanged ends. CF8M or WCB body with PCTFE or metal seats, sizes 1/2" to 4".',
        N'CF8M / WCB', N'PCTFE / Metal seat', N'Three Piece, Cryogenic, Full Port', N'-196 to +120 degree C',
        N'3-piece cryogenic full port design
ISO 5211 mounting pad
Blow-out proof stem
17-4PH stem
Ends: Threaded, Socket Weld, Butt Weld (2250 PSI), Flanged ANSI #150/300/600
Body: CF8M, WCB
Seats: PCTFE, Metal seat
For liquid nitrogen, helium, CO2 and other liquid gas
Temperature range -196 to +120 degree C
Size 1/2" to 4"');

DECLARE @SeriesName nvarchar(100) = N'Series 89C-10/20/30/60';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);

-- Idempotent: clear any prior rows for this series so re-running always yields a clean set.
DELETE FROM ProductFilterValues WHERE CategoryId = @CategoryId;
DELETE FROM CatalogProducts WHERE CategoryId = @CategoryId;
DELETE FROM CategoryFilters WHERE CategoryId = @CategoryId;

INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'Ends'),(N'Size'),(N'Body'),(N'Seat')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);

INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder FROM (VALUES (N'Ends',0),(N'Size',1),(N'Body',2),(N'Seat',3)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);

